/*
 * bitParity - returns 1 if x contains an odd number of 0's
 *   Examples: bitParity(5) = 0, bitParity(7) = 1
*/
int bitParity(int x) {
    int x1, x2, x3, x4, x5;
    x1 = x ^ (x >> 16);
    x2 = x1 ^ (x1 >> 8);
    x3 = x2 ^ (x2 >> 4);
    x4 = x3 ^ (x3 >> 2);
    x5 = x4 ^ (x4 >> 1);
    return x5 & 1;
}
```
